import{_ as t,y as r,a as l,o as u,ag as n,D as i,I as o,g as a}from"./chunks/framework.C2qfZH9T.js";const q=JSON.parse('{"title":"Gestion des commissions","description":"","frontmatter":{},"headers":[],"relativePath":"multi-vendor-marketplace/commission-management.md","filePath":"multi-vendor-marketplace/commission-management.md","lastUpdated":1782937842000}'),d={name:"multi-vendor-marketplace/commission-management.md"};function m(p,e,c,g,v,f){const s=r("ImagePopup");return u(),l("div",null,[e[0]||(e[0]=n('<h1 id="gestion-des-commissions" tabindex="-1">Gestion des commissions <a class="header-anchor" href="#gestion-des-commissions" aria-label="Permalink to &quot;Gestion des commissions&quot;">​</a></h1><p>Le système de gestion des commissions du Marketplace d&#39;ExalandStore permet aux propriétaires de plateforme (administrateurs) de définir et de gérer les taux de commission pour les vendeurs de manière flexible et claire.</p><p>Ce système aide le marché à gagner un revenu stable et donne également aux administrateurs la possibilité d&#39;accorder des taux de commission spéciaux aux vendeurs à titre de récompenses ou d&#39;incitations si nécessaire.</p><p>La gestion des commissions comporte trois parties principales :</p><p><strong>1) Pourcentage de commission administrative (taux global)</strong></p><p><strong>2) Commission du vendeur (taux personnalisé)</strong></p><p><strong>3) Rapports de ventes pour la transparence</strong></p><h3 id="pourcentage-de-commission-d-administration-taux-global" tabindex="-1">Pourcentage de commission d&#39;administration (taux global) <a class="header-anchor" href="#pourcentage-de-commission-d-administration-taux-global" aria-label="Permalink to &quot;Pourcentage de commission d&#39;administration (taux global)&quot;">​</a></h3><p>Un taux de commission global est un pourcentage standard qui s&#39;applique automatiquement à tous les vendeurs.</p><p>Il s’agit du moyen le plus simple et le plus fiable de gagner de l’argent grâce aux ventes puisque chaque vendeur de la plateforme paie le même tarif.</p><p><strong>Pourquoi c&#39;est important :</strong></p><ol><li>S&#39;assure que tous les vendeurs sont traités équitablement et équitablement.</li><li>Simple à gérer : il n&#39;est pas nécessaire de créer des commissions distinctes, sauf si cela est nécessaire.</li><li>Prend en charge le maintien d’un revenu stable pour le marché.</li></ol><p><strong>Étapes pour fixer la commission globale</strong></p><ol><li>Dans le panneau d&#39;administration, accédez à <strong>Configurer → Marketplace → Général</strong>.</li><li>Localisez le champ <strong>Pourcentage de commission administrative</strong>.</li><li>Entrez le taux de pourcentage que vous souhaitez appliquer globalement.</li><li>Cliquez sur <strong>Enregistrer la configuration</strong> — le tarif sera désormais appliqué automatiquement à tous les vendeurs.</li></ol>',14)),i(s,{src:"/images/multi-vendor-marketplace/configure_commission.png",alt:"Global Commission Configuration"}),e[1]||(e[1]=n(' <p><strong>Exemple :</strong> Si le taux global est de 10 % et qu&#39;un vendeur vend quelque chose pour 1 000 $, l&#39;administrateur recevra automatiquement 100 $ de commission, tandis que le vendeur conservera 900 $.</p><hr><h3 id="commission-du-vendeur-taux-personnalise" tabindex="-1">Commission du vendeur (taux personnalisé) <a class="header-anchor" href="#commission-du-vendeur-taux-personnalise" aria-label="Permalink to &quot;Commission du vendeur (taux personnalisé)&quot;">​</a></h3><p>Parfois, vous souhaiterez peut-être établir un taux de commission unique pour des vendeurs spécifiques.</p><p>C&#39;est ce qu&#39;on appelle un taux de commission personnalisé et il peut être supérieur ou inférieur au taux global, en fonction de l&#39;accord.</p><p><strong>Quand utiliser une commission personnalisée :</strong></p><ol><li>Motiver les nouveaux vendeurs en leur proposant des taux de commission inférieurs.</li><li>En prime pour les vendeurs qui fonctionnent très bien.</li><li>Pour des accords de partenariat uniques.</li><li>Pour des promotions à court terme ou des boosts lors des soldes saisonnières.</li></ol><p><strong>Caractéristique clé :</strong></p><ol><li>Status Toggle peut activer ou désactiver une commission personnalisée à tout moment.</li><li>Lorsqu&#39;elle est activée, la commission personnalisée remplace la commission globale pour ce vendeur spécifique.</li><li>Une fois désactivé, le vendeur revient au tarif global.</li></ol><p><strong>Comment définir une commission personnalisée pour un vendeur :</strong></p><ol><li>Dans le panneau d&#39;administration, accédez à : <strong>Marketplace → Vendeurs</strong>.</li><li>Recherchez le vendeur que vous souhaitez modifier et cliquez sur l&#39;icône <strong>Modifier</strong>.</li><li>Localisez la section <strong>Commission du vendeur</strong>.</li><li>Entrez le taux souhaité et utilisez le <strong>Status Toggle</strong> pour l&#39;activer.</li><li>Enregistrez les paramètres : le tarif personnalisé s&#39;appliquera désormais uniquement à ce vendeur.</li></ol>',12)),i(s,{src:"/images/multi-vendor-marketplace/seller_commission.png",alt:"Seller Custom Commission"}),e[2]||(e[2]=n(' <p><strong>Exemple :</strong> Si le taux global est de 10 %, mais que le vendeur A bénéficie d&#39;un taux personnalisé de 5 %, seuls 5 % seront déduits des ventes du vendeur A, tandis que les autres continueront à être facturés à 10 %.</p><hr><h3 id="rapports-de-ventes-pour-la-transparence" tabindex="-1">Rapports de ventes pour la transparence <a class="header-anchor" href="#rapports-de-ventes-pour-la-transparence" aria-label="Permalink to &quot;Rapports de ventes pour la transparence&quot;">​</a></h3><p>ExalandStore dispose d&#39;un outil de reporting des ventes intégré qui permet aux vendeurs de suivre facilement le montant des commissions qu&#39;ils ont payées au fil du temps.</p><p>Cette ouverture contribue à créer une confiance entre le marché et les vendeurs en garantissant qu&#39;il n&#39;y a pas de frais secrets.</p><p><strong>Avantages des rapports de ventes :</strong></p><ol><li>Les vendeurs peuvent suivre la commission totale versée à l’administrateur.</li><li>Fournit un aperçu de l’impact des commissions sur les bénéfices globaux.</li><li>Encourage des relations d’affaires saines.</li></ol><p><strong>Où les vendeurs peuvent trouver ce rapport :</strong></p><ol><li>Depuis le <strong>Tableau de bord du vendeur</strong>, accédez à : <strong>Rapports → Commission totale payée</strong>.</li></ol>',10)),i(s,{src:"/images/multi-vendor-marketplace/total_commission_paid_reporting.png",alt:"Total Commission Paid Reporting"}),e[3]||(e[3]=o()),e[4]||(e[4]=a("p",null,[a("strong",null,"Exemple :"),o(" Un vendeur vendant des marchandises d'une valeur de 50 000 $ avec un taux de commission de 10 % verra 5 000 $ répertorié dans la section « Commission totale payée ».")],-1))])}const _=t(d,[["render",m]]);export{q as __pageData,_ as default};
